/* ===== module: workout/superset-advance.js ===== */
/* FORK v1.947 (research Top-16 #16d): superset auto-advance polish.
   Completing a set in a superset scrolls the partner exercise's card
   into view and flashes it briefly, so the round flows without
   hunting. Purely presentational — no state changes. Permanent
   since the experiments graduation (user ruling 2026-10-23). */

function forkSupersetPartner(item, exercises) {
  if (!item?.supersetId) return null;
  return (exercises || []).find(x => x.uid !== item.uid && x.supersetId === item.supersetId && (x.sets || []).some(s => !s.complete)) || null;
}

/* #781 (pre-2.0): on a single-side exercise a round is an L row and its
   R twin (added as a pair, L first — see the + Add set handler). The
   twin is the opposite-side row next to the completed one, looking
   forward from an L row and back from an R row first, so a finished
   round never pairs with the next round's row; null for a set with no
   side or no adjacent twin. */
function forkSupersetSideTwin(item, set) {
  const side = typeof setSide === 'function' ? setSide(set) : null;
  if (!side || !item?.sets) return null;
  const i = item.sets.indexOf(set);
  if (i < 0) return null;
  const other = side === 'L' ? 'R' : 'L';
  for (const j of (side === 'L' ? [i + 1, i - 1] : [i - 1, i + 1])) {
    const s = item.sets[j];
    if (s && setSide(s) === other) return s;
  }
  return null;
}

/* #781: completing the first side of a single-side exercise does NOT
   advance — the second side is the next step; the round advances once
   both sides are done. Exercises without sides advance as before. */
function forkSupersetAdvance(item, set) {
  const twin = set ? forkSupersetSideTwin(item, set) : null;
  if (twin && !twin.complete) return;
  const draft = typeof workoutState !== 'undefined' ? workoutState.draft : null;
  const partner = forkSupersetPartner(item, draft?.exercises || []);
  if (!partner || typeof document === 'undefined') return;
  requestAnimationFrame(() => {
    const card = document.querySelector(`[data-workout-exercise="${CSS.escape(partner.uid)}"]`);
    if (!card) return;
    card.scrollIntoView({ block: 'center', behavior: 'smooth' });
    card.classList.add('fork-superset-flash');
    setTimeout(() => card.classList.remove('fork-superset-flash'), 1200);
  });
}
